using DimensionalQuantities.Roslyn.Discovery;

namespace DimensionalQuantities.Roslyn.Generators;

internal static class PowerMethodSourceEmitter
{
	public static string Emit(QuantityGenerationPlan plan) => Emit(plan, "PowerMethodExtensions");

	public static string Emit(QuantityGenerationPlan plan, string className)
	{
		string extensions = string.Join("\n\n", plan.PowerMethodOperations.GroupBy(operation => operation.Operand)
			.Select(group => RenderExtension(group.Key, group, plan)));
		return $$"""
			// <auto-generated />
			namespace DimensionalQuantities.Generated;

			internal static class {{className}}
			{
				{{extensions.Replace("\n", "\n\t")}}
			}
			""";
	}

	private static string RenderExtension(DimensionalQuantities.Dimensions.Dimension dimension,
		IEnumerable<PowerMethodOperation> operations, QuantityGenerationPlan plan)
	{
		string operand = plan.GetQuantityName(dimension);
		string methods = string.Join("\n\t", operations.Select(operation => RenderMethod(operation, plan)));
		return $$"""
			extension({{operand}} value)
			{
				{{methods}}
			}
			""";
	}

	private static string RenderMethod(PowerMethodOperation operation, QuantityGenerationPlan plan)
	{
		string result = plan.GetQuantityName(operation.Result);
		string exponentTypeName = operation.ToPowerOperation().ExponentTypeName;
		return $"public {result} {operation.MethodName}() => global::DimensionalQuantities.TypeSystem.Power<{exponentTypeName}>.Of(value);";
	}
}
